import {accountReady} from './account-client.js';
const root=document.querySelector('.feedback-page'),owner=root.dataset.owner==='true',endpoint=owner?'/api/owner-feedback':'/api/feedback';
const $=id=>document.getElementById(id),categories=['Suggestion','Bug or problem','Question','Concern','Other'],statuses=['New','Reviewing','Planned','Resolved','Closed'];
let clerk,current,next=null,generation=0;
function el(tag,text,parent){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;parent?.append(n);return n;}
function announce(text){$('feedback-status').textContent=text;}
async function api(query='',data){const token=await clerk?.session?.getToken();if(!token)throw Error('Please sign in to use private feedback.');const response=await fetch(endpoint+query,{method:data?'POST':'GET',headers:{Authorization:`Bearer ${token}`,...(data?{'Content-Type':'application/json'}:{})},body:data?JSON.stringify(data):undefined,cache:'no-store'});const result=await response.json();if(!response.ok)throw Error(result.error||'Could not load feedback.');return result;}
const attempt=fn=>async event=>{event?.preventDefault();try{await fn(event);}catch(e){announce(e.message);}};
function field(form,label,name,options,max){const l=el('label',label,form),n=el(options?'select':'textarea',undefined,l);n.name=name;n.required=true;if(max)n.maxLength=max;for(const value of options||[])el('option',value,n).value=value;return n;}
function composer(parent,create=false){const form=el('form',undefined,parent);if(create){field(form,'Category','category',categories);const l=el('label','Subject',form),input=el('input',undefined,l);input.name='subject';input.required=true;input.maxLength=120;}
 field(form,'Message','message',null,4000);el('p','Please don’t include passwords, payment information, or other sensitive personal information.',form).className='feedback-notice';const send=el('button',create?'Start conversation':'Send reply',form);let pending;
 form.addEventListener('submit',attempt(async()=>{const values=Object.fromEntries(new FormData(form)),payload={action:create?'create':'reply',...(!create?{id:current.id}:{}),...values};const signature=JSON.stringify(payload);if(!pending||pending.signature!==signature)pending={signature,id:crypto.randomUUID()};send.disabled=true;try{const result=await api('',{...payload,requestId:pending.id});pending=null;await open(result.id);await list();announce('Message sent.');}finally{send.disabled=false;}}));}
async function list(append=false){const q=owner?new URLSearchParams(new FormData($('filters'))):new URLSearchParams();for(const [k,v]of [...q])if(!v)q.delete(k);if(append&&next!==null)q.set('offset',next);const data=await api('?'+q);if(!append)$('conversations').replaceChildren();if(!data.items.length&&!append)el('p','No conversations yet.',$('conversations'));for(const c of data.items){const b=el('button',`${c.unread?'Unread · ':''}${c.subject} — ${c.status}${c.archived?' · Archived':''}`,$('conversations'));b.className='conversation-button';b.setAttribute('aria-current',String(current?.id===c.id));b.addEventListener('click',attempt(()=>open(c.id)));}next=data.nextOffset;$('more').hidden=next===null;}
function message(m,parent){const n=el('article',undefined,parent);n.className='message'+(m.senderType==='user'?' message-user':'');el('small',`${m.senderType==='owner'?'EZEATS Team':owner?'User':'You'} · ${new Date(m.createdAt).toLocaleString()}`,n);el('div',m.text,n);}
async function open(id){const run=++generation;announce('Loading conversation…');const data=await api('?id='+encodeURIComponent(id));if(run!==generation)return;current=data.conversation;history.replaceState(null,'',location.pathname+'?id='+encodeURIComponent(id));const d=$('detail');d.replaceChildren();root.classList.add('is-open');const heading=el('h2',current.subject,d);heading.tabIndex=-1;heading.focus();el('p',`${current.category} · ${current.status}${current.archived?' · Archived':''}`,d);
 const older=el('button','Earlier messages',d),messages=el('div',undefined,d);messages.className='messages';messages.setAttribute('role','log');messages.setAttribute('aria-label','Conversation messages');let before=data.before;older.hidden=!before;older.addEventListener('click',attempt(async()=>{const page=await api(`?id=${encodeURIComponent(id)}&before=${before}`);const fragment=document.createDocumentFragment();page.messages.forEach(m=>message(m,fragment));messages.prepend(fragment);before=page.before;older.hidden=!before;}));data.messages.forEach(m=>message(m,messages));
 if(!current.archived&&current.status!=='Closed')composer(d);else el('p','This conversation is closed. You can still read its messages.',d);
 if(owner&&!current.archived){const form=el('form',undefined,d),select=field(form,'Conversation status','status',statuses);select.value=current.status;el('button','Update status',form);form.addEventListener('submit',attempt(async()=>{await api('',{action:'status',id,version:current.version,status:select.value});await open(id);await list();}));const archive=el('button','Archive conversation',d);archive.addEventListener('click',attempt(async()=>{await api('',{action:'archive',id,version:current.version});await open(id);await list();}));}
 await api('',{action:'read',id,sequence:current.sequence});await list();announce('Conversation loaded.');}
$('back').onclick=()=>{root.classList.remove('is-open');history.replaceState(null,'',location.pathname);(owner?$('filters').querySelector('select'):$('new')).focus();};$('new').onclick=()=>{generation++;current=null;history.replaceState(null,'',location.pathname);$('detail').replaceChildren();el('h2','New conversation',$('detail'));composer($('detail'),true);root.classList.add('is-open');$('detail').querySelector('select').focus();};
for(const [name,values]of [['category',categories],['status',statuses]])for(const v of values)el('option',v,$('filters').elements[name]).value=v;
$('filters').hidden=!owner;$('new').hidden=owner;$('filters').onsubmit=attempt(()=>list());$('more').onclick=attempt(()=>list(true));
async function init(){clerk=await accountReady();await list();$('inbox').hidden=false;announce('Inbox ready.');const id=new URLSearchParams(location.search).get('id');if(id)await open(id);}
$('retry').onclick=attempt(init);await attempt(init)();
if(clerk)clerk.addListener(({session})=>{if(!session){generation++;current=null;$('detail').replaceChildren();$('conversations').replaceChildren();$('inbox').hidden=true;announce('Signed out. Sign in to view your conversations.');}});
